(function () {
  'use strict';

  let CURRENT_MARKET = 'nse';
  let CURRENT_VIEW = 'orderblock';
  let MARKET_DATA = null;
  let ACTIVE_MODAL_SYMBOL = null;
  let HOVERED_SYMBOL = 'BTC';
  let hoverTimer = null;
  let activeHoverElement = null;
  let GUEST_BLUR_ACTIVE = false;

  function getCurrency() {
    if (MARKET_DATA && MARKET_DATA.currency) return MARKET_DATA.currency;
    if (CURRENT_MARKET === 'nse') return '₹';
    return '$';
  }

  function fmtPrice(p) {
    if (p === undefined || p === null || isNaN(p)) return '--';
    const c = getCurrency();
    const num = Number(p);
    if (num >= 1000) {
      return c + num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    } else if (num >= 1) {
      return c + num.toFixed(2);
    } else if (num >= 0.01) {
      return c + num.toFixed(4);
    } else {
      return c + num.toFixed(6);
    }
  }

  function fmtLevel(p) {
    if (p === undefined || p === null || isNaN(p)) return '--';
    const num = Number(p);
    if (num >= 100) return num.toFixed(1);
    if (num >= 1) return num.toFixed(2);
    if (num >= 0.01) return num.toFixed(4);
    return num.toFixed(7);
  }

  window.toggleGuestBlur = function() {
    GUEST_BLUR_ACTIVE = !GUEST_BLUR_ACTIVE;
    const txt = document.getElementById('blurStateText');
    if (txt) {
      txt.textContent = GUEST_BLUR_ACTIVE ? 'ON' : 'OFF';
      txt.style.color = GUEST_BLUR_ACTIVE ? '#ff2a55' : '#38bdf8';
    }
    const cards = document.querySelectorAll('.master-card-sym, .source-sym, .buildup-sym, .pick-title b');
    cards.forEach(el => {
      if (GUEST_BLUR_ACTIVE) {
        el.style.filter = 'blur(4px)';
        el.style.userSelect = 'none';
      } else {
        el.style.filter = 'none';
        el.style.userSelect = 'auto';
      }
    });
  };

  window.switchMarket = async function(mkt) {
    CURRENT_MARKET = mkt;
    document.querySelectorAll('.mkt-tab').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.market === mkt);
    });

    // Try backend if local server is running
    try {
      const res = await fetch('/api/market/switch', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ market: mkt })
      });
      if (res.ok) {
        const d = await res.json();
        if (d.ok && d.summary) {
          if (d.summary.top_bullish && d.summary.top_bullish.length > 0) {
            HOVERED_SYMBOL = d.summary.top_bullish[0].symbol;
          }
          updateMarketState(d.summary);
          return;
        }
      }
    } catch (e) {}

    // Fallback static data engine (100% works on GitHub Pages)
    if (OB_FALLBACK_DATA[mkt]) {
      const fallback = JSON.parse(JSON.stringify(OB_FALLBACK_DATA[mkt]));
      if (fallback.top_bullish && fallback.top_bullish.length > 0) {
        HOVERED_SYMBOL = fallback.top_bullish[0].symbol;
      }
      updateMarketState(fallback);
    }
  };

  // DOM REFS
  const bullContainer = document.getElementById('bullish-cards-container');
  const bearContainer = document.getElementById('bearish-cards-container');
  const depthSvg = document.getElementById('market-depth-svg');
  const sectorSvg = document.getElementById('sector-flow-svg');
  const sankeySvg = document.getElementById('sankey-canvas');
  const stockModalOverlay = document.getElementById('stockModalOverlay');

  function initDataStream() {
    try {
      const evtSource = new EventSource('/api/stream');
      evtSource.onmessage = function (e) {
        try {
          const data = JSON.parse(e.data);
          updateMarketState(data);
        } catch (err) {}
      };
      evtSource.onerror = function () {
        evtSource.close();
        startClientPulse();
      };
    } catch (e) {
      startClientPulse();
    }
  }

  function startClientPulse() {
    if (!MARKET_DATA && OB_FALLBACK_DATA[CURRENT_MARKET]) {
      updateMarketState(JSON.parse(JSON.stringify(OB_FALLBACK_DATA[CURRENT_MARKET])));
    }
    setInterval(tickClientSideData, 2500);
  }

  async function tickClientSideData() {
    if (!MARKET_DATA || !MARKET_DATA.stocks) return;

    if (CURRENT_MARKET === 'crypto' && typeof fetch !== 'undefined') {
      try {
        const pairs = ['BTC-USD', 'ETH-USD', 'SOL-USD', 'DOGE-USD'];
        const statsPromises = pairs.map(p =>
          fetch(`https://api.exchange.coinbase.com/products/${p}/stats`)
            .then(r => r.ok ? r.json() : null)
            .then(data => ({ sym: p.split('-')[0], data }))
            .catch(() => null)
        );
        const results = await Promise.all(statsPromises);
        results.forEach(res => {
          if (res && res.data && res.data.last && MARKET_DATA.stocks[res.sym]) {
            const st = MARKET_DATA.stocks[res.sym];
            st.cmp = parseFloat(res.data.last);
            const open = parseFloat(res.data.open) || st.base_price;
            st.change_pct = parseFloat((((st.cmp - open) / open) * 100).toFixed(2));
          }
        });
      } catch (e) {}
    }

    const symKeys = Object.keys(MARKET_DATA.stocks);
    for (let k = 0; k < 2; k++) {
      const randSym = symKeys[Math.floor(Math.random() * symKeys.length)];
      const stock = MARKET_DATA.stocks[randSym];
      if (stock) {
        const deltaPct = (Math.random() - 0.49) * 0.08;
        stock.cmp = +(stock.cmp * (1 + deltaPct / 100)).toFixed(stock.cmp > 100 ? 2 : 4);
      }
    }

    const now = new Date();
    MARKET_DATA.timestamp = now.toTimeString().split(' ')[0];

    // If orderblock screen is currently active, re-render
    const obTab = document.getElementById('tab-orderblock');
    if (obTab && obTab.classList.contains('active')) {
      renderOrderBlockView(MARKET_DATA);
    }
  }

  window.initOrderBlockScreen = function() {
    // Sync with TradeRadar currentMarketSegment if set
    if (typeof currentMarketSegment !== 'undefined') {
      if (currentMarketSegment === 'crypto') {
        CURRENT_MARKET = 'crypto';
      } else if (currentMarketSegment === 'metals') {
        CURRENT_MARKET = 'us';
      } else {
        CURRENT_MARKET = 'nse';
      }
    }
    
    // Sync market switcher buttons in UI
    document.querySelectorAll('.mkt-tab').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.market === CURRENT_MARKET);
    });

    if (OB_FALLBACK_DATA[CURRENT_MARKET]) {
      const copy = JSON.parse(JSON.stringify(OB_FALLBACK_DATA[CURRENT_MARKET]));
      if (copy.top_bullish && copy.top_bullish.length > 0) {
        HOVERED_SYMBOL = copy.top_bullish[0].symbol;
      }
      updateMarketState(copy);
    }
  };

  // Bridge to TradeRadar TradingView Chart Engine
  window.loadStockIntoRadar = function (sym) {
    if (!sym) return;
    const symUpper = sym.toUpperCase().trim();
    if (typeof window.openTradeTicket === 'function') {
      window.openTradeTicket(symUpper);
    } else if (typeof window.openStockModal === 'function') {
      window.openStockModal(symUpper);
    }
  };

  function updateMarketState(data) {
    MARKET_DATA = data;
    
    // Sync market switcher buttons in UI
    const curMkt = data.market || 'crypto';
    document.querySelectorAll('.mkt-tab').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.market === curMkt);
    });

    // Set or refresh initial hovered stock for the market
    if ((!HOVERED_SYMBOL || !data.stocks[HOVERED_SYMBOL]) && data.top_bullish && data.top_bullish.length > 0) {
      HOVERED_SYMBOL = data.top_bullish[0].symbol;
    }

    renderScatterRadar();
    renderMarketDepth(data.status);
    renderDashboardPicks(data.top_bullish, data.top_bearish);
    renderSectorFlow(data.sectors);
    
    // Always render Order Block view
    renderOrderBlockView(data);

    if (ACTIVE_MODAL_SYMBOL && data.stocks[ACTIVE_MODAL_SYMBOL]) {
      renderModalData(data.stocks[ACTIVE_MODAL_SYMBOL]);
    }

    const statusText = document.getElementById('market-status-text');
    if (statusText) statusText.textContent = `Live ${data.timestamp || '11:05'}`;
    const depthTime = document.getElementById('depth-time');
    if (depthTime && data.timestamp) depthTime.textContent = data.timestamp;
  }

  // ---------------- SCATTER RADAR DOT MATRIX ----------------
  function renderScatterRadar() {
    const bullDots = document.getElementById('bull-scatter-dots');
    const bearDots = document.getElementById('bear-scatter-dots');
    if (!bullDots || !bearDots || bullDots.children.length > 0) return;

    let bHtml = '', rHtml = '';
    for (let i = 0; i < 28; i++) {
      const delay = (i * 0.12).toFixed(2);
      bHtml += `<span class="scatter-dot bull" style="animation-delay:${delay}s;"></span>`;
      rHtml += `<span class="scatter-dot bear" style="animation-delay:${delay}s;"></span>`;
    }
    bullDots.innerHTML = bHtml;
    bearDots.innerHTML = rHtml;
  }

  // ---------------- 1. MARKET DEPTH ADVANCE/DECLINE CURVE ----------------
  function renderMarketDepth(status) {
    if (!status || !depthSvg) return;

    const bullCount = document.getElementById('bull-count');
    const bearCount = document.getElementById('bear-count');
    if (bullCount) bullCount.textContent = status.advance || 18;
    if (bearCount) bearCount.textContent = status.decline || 12;

    const W = 700, H = 80;
    const midX = W / 2;
    const bBars = status.depth_bullish || [14, 20, 26, 32, 40, 48, 56, 64, 72, 78];
    const rBars = status.depth_bearish || [12, 16, 22, 28, 34, 42, 48, 54, 60, 66];

    let svgHtml = `
      <defs>
        <linearGradient id="bullGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#00ff87" stop-opacity="0.35"/>
          <stop offset="100%" stop-color="#00ff87" stop-opacity="0.0"/>
        </linearGradient>
        <linearGradient id="bearGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#ff2a55" stop-opacity="0.35"/>
          <stop offset="100%" stop-color="#ff2a55" stop-opacity="0.0"/>
        </linearGradient>
      </defs>
      <line x1="${midX}" y1="0" x2="${midX}" y2="${H}" stroke="#334155" stroke-dasharray="3,3" stroke-width="1.5"/>
      <line x1="0" y1="${H-2}" x2="${W}" y2="${H-2}" stroke="#1e293b" stroke-width="1"/>
    `;

    const barW = 14;
    const stepB = (midX - 25) / bBars.length;
    let bPath = `M 20 ${H-2} `;
    bBars.forEach((val, i) => {
      const x = 20 + i * stepB;
      const h = Math.min(H - 10, val * 0.9);
      const y = H - 2 - h;
      svgHtml += `<rect x="${x}" y="${y}" width="${barW}" height="${h}" rx="2" fill="#00ff87" fill-opacity="0.55"/>`;
      svgHtml += `<circle cx="${x + barW/2}" cy="${y}" r="2.5" fill="#00ff87" filter="drop-shadow(0 0 4px #00ff87)"/>`;
      bPath += `L ${x + barW/2} ${y} `;
    });
    bPath += `L ${midX} ${H-2} Z`;

    const stepR = (midX - 25) / rBars.length;
    let rPath = `M ${midX} ${H-2} `;
    rBars.forEach((val, i) => {
      const x = midX + 15 + i * stepR;
      const h = Math.min(H - 10, val * 0.85);
      const y = H - 2 - h;
      svgHtml += `<rect x="${x}" y="${y}" width="${barW}" height="${h}" rx="2" fill="#ff2a55" fill-opacity="0.55"/>`;
      svgHtml += `<circle cx="${x + barW/2}" cy="${y}" r="2.5" fill="#ff2a55" filter="drop-shadow(0 0 4px #ff2a55)"/>`;
      rPath += `L ${x + barW/2} ${y} `;
    });
    rPath += `L ${W-20} ${H-2} Z`;

    svgHtml += `<path d="${bPath}" fill="url(#bullGrad)"/>`;
    svgHtml += `<path d="${rPath}" fill="url(#bearGrad)"/>`;

    depthSvg.innerHTML = svgHtml;
  }

  // ---------------- 2. TOP PICKS CARDS (HOME DASHBOARD) ----------------
  function renderDashboardPicks(bulls, bears) {
    if (!bullContainer || !bearContainer) return;
    bullContainer.innerHTML = (bulls || []).map(stock => createPickCardHtml(stock, 'bull')).join('');
    bearContainer.innerHTML = (bears || []).map(stock => createPickCardHtml(stock, 'bear')).join('');
  }

  function createPickCardHtml(s, type) {
    const isBull = type === 'bull';
    const tagClass = isBull ? 'bull' : 'bear';
    const chgClass = s.change_pct >= 0 ? 'up' : 'down';
    const sign = s.change_pct > 0 ? '+' : '';

    return `
      <div class="pick-card hud-card ${isBull ? 'bull-card bull' : 'bear-card bear'}" onclick="openStockModal('${s.symbol}')">
        <div class="pick-info">
          <div class="pick-tag-row">
            <span class="tag-badge ${tagClass}">${isBull ? 'BULL' : 'BEAR'}</span>
            <span class="pick-symbol blur-target">${s.symbol}</span>
          </div>
          <span class="pick-meta">${s.sector} · ${s.category}</span>
        </div>

        <div class="micro-chart">
          ${renderMicroCandles(s.candles || s.sparkline, isBull, s.ob_high, s.ob_low)}
        </div>

        <div class="pick-numbers">
          <div class="pick-price">${fmtPrice(s.cmp)}</div>
          <div class="pick-chg ${chgClass}">${sign}${s.change_pct.toFixed(2)}%</div>
        </div>
      </div>
    `;
  }

  function renderMicroCandles(candles, isBull, obH, obL) {
    const W = 110, H = 40;
    if (!candles || candles.length < 2) return '';
    const subset = candles.slice(-14);
    const lows = subset.map(c => c.low);
    const highs = subset.map(c => c.high);
    const minP = Math.min(...lows, obL || 999999);
    const maxP = Math.max(...highs, obH || 0);
    const range = maxP - minP || 1;
    const yVal = p => H - 4 - ((p - minP) / range) * (H - 8);

    const obMid = ((obH || 0) + (obL || 0)) / 2;
    const obY = obMid ? yVal(obMid) : H / 2;
    const barW = Math.max(3.2, Math.floor((W - 20) / subset.length) - 2);

    let html = `<svg viewBox="0 0 ${W} ${H}" style="width:100%; height:100%; overflow:visible;">
      <line x1="0" y1="${obY.toFixed(1)}" x2="${W}" y2="${obY.toFixed(1)}" stroke="#fbbf24" stroke-dasharray="2,2" stroke-width="1" opacity="0.8"/>
      <text x="2" y="${Math.max(8, obY - 2).toFixed(1)}" fill="#fbbf24" font-size="6.5" font-family="JetBrains Mono" font-weight="800">OB</text>
    `;

    subset.forEach((c, i) => {
      const x = 14 + i * (barW + 2);
      const isUp = c.close >= c.open;
      const col = isUp ? '#00ff87' : '#ff2a55';
      const top = yVal(Math.max(c.open, c.close));
      const bot = yVal(Math.min(c.open, c.close));
      const h = Math.max(1.5, bot - top);
      const wickT = yVal(c.high);
      const wickB = yVal(c.low);

      html += `
        <line x1="${(x + barW / 2).toFixed(1)}" y1="${wickT.toFixed(1)}" x2="${(x + barW / 2).toFixed(1)}" y2="${wickB.toFixed(1)}" stroke="${col}" stroke-width="0.85" opacity="0.85"/>
        <rect x="${x.toFixed(1)}" y="${top.toFixed(1)}" width="${barW}" height="${h.toFixed(1)}" fill="${col}" opacity="0.95" rx="0.5"/>
      `;
    });

    html += `</svg>`;
    return html;
  }

  function renderMicroSparkline(points, isBull, obH, obL) {
    return renderMicroCandles(points, isBull, obH, obL);
  }

  // ---------------- 3. SECTOR FLOW SVG CHART ----------------
  function renderSectorFlow(sectors) {
    if (!sectorSvg || !sectors) return;
    const W = 350, H = 120;
    const midY = H / 2;

    let svgHtml = `
      <line x1="0" y1="${midY}" x2="${W}" y2="${midY}" stroke="#1e293b" stroke-width="1"/>
      <text x="${W - 35}" y="${midY - 4}" fill="#475569" font-size="8" font-family="JetBrains Mono">0.00%</text>
    `;

    sectors.forEach((sec) => {
      const path = sec.path || [];
      if (path.length < 2) return;
      const isUp = sec.chg >= 0;
      const stroke = isUp ? '#00ff87' : '#ff2a55';

      const coords = path.map((val, i) => {
        const x = (i / (path.length - 1)) * (W - 50);
        const y = midY - (val * 24);
        return `${x.toFixed(1)},${y.toFixed(1)}`;
      });

      svgHtml += `<polyline fill="none" stroke="${stroke}" stroke-width="1.5" points="${coords.join(' ')}" opacity="0.75" filter="drop-shadow(0 0 2px ${stroke})"/>`;
      const lastX = W - 48;
      const lastY = midY - (sec.chg * 24);
      svgHtml += `<circle cx="${lastX}" cy="${lastY}" r="2" fill="${stroke}"/>`;
    });

    sectorSvg.innerHTML = svgHtml;
  }

  // ---------------- 4. CYBERPUNK ORDER BLOCK HUD (SCREEN 3) ----------------
  function renderOrderBlockView(data) {
    const srcList = document.getElementById('ob-source-list');
    const masterPicks = document.getElementById('ob-master-picks');

    if (!srcList || !data.stocks) return;

    // Render left stock list with onmouseover triggering laser stream
    const stockEntries = Object.values(data.stocks).sort((a, b) => (b.change_pct || 0) - (a.change_pct || 0));
    srcList.innerHTML = stockEntries.map(s => {
      const isHovered = s.symbol === HOVERED_SYMBOL;
      return `
        <div class="source-row ${isHovered ? 'active' : ''}" 
             id="src-item-${s.symbol}"
             data-sym="${s.symbol}"
             onmouseenter="showStockHover('${s.symbol}', this, event, 'compact')"
             onmouseleave="hideStockHover()"
             onclick="openStockModal('${s.symbol}')">
          <span class="source-sym">${s.symbol}</span>
          <span class="source-chg" style="color: ${s.change_pct >= 0 ? 'var(--bull-green)' : 'var(--bear-red)'}">
            ${s.change_pct > 0 ? '+' : ''}${s.change_pct.toFixed(2)}%
          </span>
        </div>
      `;
    }).join('');

    // Categorization overlay (All 6 columns matching video)
    let cats = data.categories;
    if (!cats) {
      cats = { long_buildup: [], short_covering: [], short_buildup: [], long_unwinding: [] };
      stockEntries.forEach(s => {
        const cat = (s.category || '').toUpperCase();
        if (cat.includes('LONG') && cat.includes('BUILD')) cats.long_buildup.push(s);
        else if (cat.includes('SHORT') && cat.includes('COVER')) cats.short_covering.push(s);
        else if (cat.includes('SHORT') && cat.includes('BUILD')) cats.short_buildup.push(s);
        else if (cat.includes('LONG') && cat.includes('UNWIND')) cats.long_unwinding.push(s);
        else if (s.change_pct >= 2) cats.long_buildup.push(s);
        else if (s.change_pct >= 0) cats.short_covering.push(s);
        else if (s.change_pct <= -2) cats.short_buildup.push(s);
        else cats.long_unwinding.push(s);
      });
    }
    const colLong1 = document.getElementById('col-long-buildup-1');
    const colLong2 = document.getElementById('col-long-buildup-2');
    const colShortCov = document.getElementById('col-short-covering');
    const colShortBd1 = document.getElementById('col-short-buildup-1');
    const colShortBd2 = document.getElementById('col-short-buildup-2');
    const colLongUnw = document.getElementById('col-long-unwinding');

    const longList = (cats.long_buildup || []).slice().sort((a, b) => (b.change_pct || 0) - (a.change_pct || 0));
    const shortCovList = (cats.short_covering || []).slice().sort((a, b) => (b.change_pct || 0) - (a.change_pct || 0));
    const shortBdList = (cats.short_buildup || []).slice().sort((a, b) => (b.change_pct || 0) - (a.change_pct || 0));
    const longUnwList = (cats.long_unwinding || []).slice().sort((a, b) => (b.change_pct || 0) - (a.change_pct || 0));

    if (colLong1) colLong1.innerHTML = longList.slice(0, 4).map(s => createBuildupItemHtml(s)).join('');
    if (colLong2) colLong2.innerHTML = (longList.length > 4 ? longList.slice(4, 8) : longList.slice(0, 4)).map(s => createBuildupItemHtml(s)).join('');
    if (colShortCov) colShortCov.innerHTML = shortCovList.slice(0, 4).map(s => createBuildupItemHtml(s)).join('');
    if (colShortBd1) colShortBd1.innerHTML = shortBdList.slice(0, 4).map(s => createBuildupItemHtml(s)).join('');
    if (colShortBd2) colShortBd2.innerHTML = (shortBdList.length > 4 ? shortBdList.slice(4, 8) : shortBdList.slice(0, 4)).map(s => createBuildupItemHtml(s)).join('');
    if (colLongUnw) colLongUnw.innerHTML = longUnwList.slice(0, 4).map(s => createBuildupItemHtml(s)).join('');

    // Master picks (right: exactly 3 Bullish + 3 Bearish = 6 Master Cards)
    if (masterPicks) {
      const topBull = (data.top_bullish || stockEntries.filter(s => s.change_pct >= 0)).slice().sort((a, b) => (b.change_pct || 0) - (a.change_pct || 0)).slice(0, 3);
      const topBear = (data.top_bearish || stockEntries.filter(s => s.change_pct < 0)).slice().sort((a, b) => (a.change_pct || 0) - (b.change_pct || 0)).slice(0, 3);
      const topPicks = [...topBull, ...topBear];
      masterPicks.innerHTML = topPicks.map(s => createMasterCardHtml(s)).join('');
    }

    // Populate Top Scatter Radar Dots
    renderTopScatterDots();

    // Render Full SVG Neural Canvas with 70+ live background flow lines
    renderSankeyCanvas(data);
  }

  function renderTopScatterDots() {
    const bullDots = document.getElementById('bull-scatter-dots');
    const bearDots = document.getElementById('bear-scatter-dots');
    if (bullDots && !bullDots.hasChildNodes()) {
      bullDots.innerHTML = Array.from({ length: 18 }).map((_, i) => 
        `<span class="scatter-dot bull" style="animation-delay: ${(i * 0.12).toFixed(2)}s; opacity: ${(0.3 + (i % 5) * 0.15).toFixed(2)};"></span>`
      ).join('');
    }
    if (bearDots && !bearDots.hasChildNodes()) {
      bearDots.innerHTML = Array.from({ length: 18 }).map((_, i) => 
        `<span class="scatter-dot bear" style="animation-delay: ${(i * 0.11).toFixed(2)}s; opacity: ${(0.3 + (i % 5) * 0.15).toFixed(2)};"></span>`
      ).join('');
    }
  }

  // ============================================================
  // NEURAL SANKEY CANVAS & LIVE LASER WAVE ENGINE (MATCHING VIDEO)
  // ============================================================
    let SANKEY_INITIALIZED_MARKET = null;

  function initStaticSankeyCanvas(marketKey) {
    const sankeySvg = document.getElementById('sankey-canvas');
    if (!sankeySvg) return;
    const W = 740, H = 680;
    const midY = H / 2;
    const slitX = 330;
    const bgOpacity = '0.24';

    let svgHtml = `
      <defs>
        <filter id="neonLaser" x="-30%" y="-30%" width="160%" height="160%">
          <feGaussianBlur stdDeviation="5" result="glow"/>
          <feMerge>
            <feMergeNode in="glow"/>
            <feMergeNode in="glow"/>
            <feMergeNode in="SourceGraphic"/>
          </feMerge>
        </filter>
        <filter id="greenGlow" x="-20%" y="-20%" width="140%" height="140%">
          <feGaussianBlur stdDeviation="3" result="glow"/>
          <feMerge>
            <feMergeNode in="glow"/>
            <feMergeNode in="SourceGraphic"/>
          </feMerge>
        </filter>
        <filter id="redGlow" x="-20%" y="-20%" width="140%" height="140%">
          <feGaussianBlur stdDeviation="3" result="glow"/>
          <feMerge>
            <feMergeNode in="glow"/>
            <feMergeNode in="SourceGraphic"/>
          </feMerge>
        </filter>
        <linearGradient id="gridBlue" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stop-color="#00f0ff" stop-opacity="0.04"/>
          <stop offset="50%" stop-color="#00f0ff" stop-opacity="0.25"/>
          <stop offset="100%" stop-color="#00f0ff" stop-opacity="0.0"/>
        </linearGradient>
      </defs>

      <!-- Horizontal Benchmark Gridlines -->
      <line x1="0" y1="${midY - 180}" x2="${W}" y2="${midY - 180}" stroke="url(#gridBlue)" stroke-width="1"/>
      <line x1="0" y1="${midY}" x2="${W}" y2="${midY}" stroke="url(#gridBlue)" stroke-width="1.5" stroke-dasharray="4,4"/>
      <line x1="0" y1="${midY + 180}" x2="${W}" y2="${midY + 180}" stroke="url(#gridBlue)" stroke-width="1"/>

      <!-- Static Background Neural Streams (Runs at smooth 60fps GPU) -->
      <g id="sankey-bg-streams">
    `;

    // 44 Green Neural Streams
    for (let i = 0; i < 44; i++) {
      const startY = 12 + i * 7.2;
      const endY = 35 + (i * 6.8) % 285;
      const cp1X = 90 + (i % 6) * 18;
      const cp2X = 210 + (i % 5) * 20;
      const isSlow = i % 2 === 0;
      const pathD = `M 0 ${startY.toFixed(1)} C ${cp1X} ${startY.toFixed(1)}, ${cp2X} ${endY.toFixed(1)}, ${slitX} ${endY.toFixed(1)}`;
      svgHtml += `<path d="${pathD}" fill="none" class="bg-stream-line bull ${isSlow ? 'slow' : ''}" stroke="#00ff87" stroke-width="1.2" opacity="${bgOpacity}"/>`;
      if (i % 4 === 0) {
        const dur = (1.4 + (i % 3) * 0.4).toFixed(1);
        const delay = ((i * 0.18) % 1.2).toFixed(2);
        svgHtml += `
          <circle r="2.2" fill="#ffffff" filter="url(#greenGlow)" opacity="0.95">
            <animateMotion path="${pathD}" dur="${dur}s" begin="${delay}s" repeatCount="indefinite"/>
          </circle>
        `;
      }
    }

    // 44 Red Neural Streams
    for (let i = 0; i < 44; i++) {
      const startY = midY + 12 + i * 7.2;
      const endY = midY + 35 + (i * 6.8) % 285;
      const cp1X = 90 + (i % 6) * 18;
      const cp2X = 210 + (i % 5) * 20;
      const isSlow = i % 2 === 0;
      const pathD = `M 0 ${startY.toFixed(1)} C ${cp1X} ${startY.toFixed(1)}, ${cp2X} ${endY.toFixed(1)}, ${slitX} ${endY.toFixed(1)}`;
      svgHtml += `<path d="${pathD}" fill="none" class="bg-stream-line bear ${isSlow ? 'slow' : ''}" stroke="#ff2a55" stroke-width="1.2" opacity="${bgOpacity}"/>`;
      if (i % 4 === 0) {
        const dur = (1.4 + (i % 3) * 0.4).toFixed(1);
        const delay = ((i * 0.18) % 1.2).toFixed(2);
        svgHtml += `
          <circle r="2.2" fill="#ffffff" filter="url(#redGlow)" opacity="0.95">
            <animateMotion path="${pathD}" dur="${dur}s" begin="${delay}s" repeatCount="indefinite"/>
          </circle>
        `;
      }
    }

    // Streams fanning out from slit into columns
    for (let i = 0; i < 22; i++) {
      const startY = 45 + i * 13;
      const endY = 30 + (i * 15) % 310;
      const pathD = `M ${slitX} ${startY} C ${slitX + 60} ${startY}, ${slitX + 180} ${endY}, ${W} ${endY}`;
      svgHtml += `<path d="${pathD}" fill="none" class="bg-stream-line bull" stroke="#00ff87" stroke-width="1.0" opacity="${bgOpacity}"/>`;
      if (i % 5 === 0) {
        svgHtml += `
          <circle r="1.8" fill="#00ff87" filter="url(#greenGlow)" opacity="0.9">
            <animateMotion path="${pathD}" dur="1.6s" begin="${(i*0.2).toFixed(1)}s" repeatCount="indefinite"/>
          </circle>
        `;
      }
    }
    for (let i = 0; i < 22; i++) {
      const startY = midY + 45 + i * 13;
      const endY = midY + 30 + (i * 15) % 310;
      const pathD = `M ${slitX} ${startY} C ${slitX + 60} ${startY}, ${slitX + 180} ${endY}, ${W} ${endY}`;
      svgHtml += `<path d="${pathD}" fill="none" class="bg-stream-line bear" stroke="#ff2a55" stroke-width="1.0" opacity="${bgOpacity}"/>`;
      if (i % 5 === 0) {
        svgHtml += `
          <circle r="1.8" fill="#ff2a55" filter="url(#redGlow)" opacity="0.9">
            <animateMotion path="${pathD}" dur="1.6s" begin="${(i*0.2).toFixed(1)}s" repeatCount="indefinite"/>
          </circle>
        `;
      }
    }

    svgHtml += `</g>`;

    // Central Hourglass Waist Silhouette & Slit
    svgHtml += `
      <g id="sankey-slit-pillar">
        <path d="M ${slitX - 28} 8 Q ${slitX + 10} ${midY}, ${slitX - 28} ${H - 8} L ${slitX + 28} ${H - 8} Q ${slitX - 10} ${midY}, ${slitX + 28} 8 Z" fill="#03060f" stroke="#121e33" stroke-width="1.6"/>
        <rect x="${slitX - 18}" y="10" width="36" height="42" fill="none" stroke="#00ff87" stroke-width="1.8" opacity="0.85" filter="url(#greenGlow)"/>
        <circle cx="${slitX}" cy="31" r="4" fill="#00ff87" opacity="0.9"/>
        <rect x="${slitX - 18}" y="${H - 52}" width="36" height="42" fill="none" stroke="#ff2a55" stroke-width="1.8" opacity="0.85" filter="url(#redGlow)"/>
        <circle cx="${slitX}" cy="${H - 31}" r="4" fill="#ff2a55" opacity="0.9"/>
        <line x1="${slitX}" y1="8" x2="${slitX}" y2="${H - 8}" stroke="#00f0ff" stroke-width="2.2" stroke-dasharray="4,4" opacity="0.9" filter="drop-shadow(0 0 10px #00f0ff)"/>
      </g>
    `;

    // High-performance Dedicated Active Laser Layer (Updated instantaneously on hover)
    svgHtml += `<g id="active-laser-layer"></g>`;

    sankeySvg.innerHTML = svgHtml;
    SANKEY_INITIALIZED_MARKET = marketKey;
  }

  function renderLaserTrajectory(sym) {
    const laserLayer = document.getElementById('active-laser-layer');
    if (!laserLayer || !MARKET_DATA || !MARKET_DATA.stocks) return;

    const data = MARKET_DATA;
    let stock = data.stocks[sym];
    if (!stock) {
      const symUpper = String(sym || '').toUpperCase();
      const k = Object.keys(data.stocks).find(key => key.toUpperCase() === symUpper);
      if (k) stock = data.stocks[k];
    }
    if (!stock) {
      laserLayer.innerHTML = '';
      return;
    }

    const W = 740, H = 680;
    const midY = H / 2;
    const slitX = 330;
    const isBull = stock.change_pct >= 0;
    const laserColor = isBull ? '#00ff87' : '#ff2a55';

    const topBull = (data.top_bullish || []).map(s => s.symbol);
    const topBear = (data.top_bearish || []).map(s => s.symbol);
    const bullRank = topBull.indexOf(stock.symbol);
    const bearRank = topBear.indexOf(stock.symbol);

    // Calculate dynamic startY matching the hovered stock row in the left list!
    let startY = midY;
    const rowEl = document.getElementById(`src-item-${stock.symbol}`) || document.querySelector(`.source-row[data-sym="${stock.symbol}"]`);
    const listEl = document.getElementById('ob-source-list');
    if (rowEl && listEl && listEl.clientHeight > 0) {
      const rowRect = rowEl.getBoundingClientRect();
      const listRect = listEl.getBoundingClientRect();
      if (listRect.height > 0) {
        const relRatio = (rowRect.top + rowRect.height / 2 - listRect.top) / listRect.height;
        startY = Math.max(16, Math.min(H - 16, relRatio * H));
      }
    } else {
      startY = isBull ? (midY - 140) : (midY + 140);
    }

    const startX = 0;
    const apexY = isBull ? Math.min(startY, 85) : Math.max(startY, H - 85);
    const slitTargetY = isBull ? 31 : (H - 31);

    let laserPath = `M ${startX} ${startY.toFixed(1)} `;
    laserPath += `C 70 ${startY.toFixed(1)}, 140 ${apexY.toFixed(1)}, 230 ${apexY.toFixed(1)} `;
    laserPath += `S ${slitX - 40} ${slitTargetY}, ${slitX} ${slitTargetY} `;

    let conduitTargetY = midY;
    if (bullRank !== -1) {
      conduitTargetY = 65 + bullRank * 110;
    } else if (bearRank !== -1) {
      conduitTargetY = midY + 50 + bearRank * 110;
    } else {
      conduitTargetY = isBull ? (midY - 80) : (midY + 80);
    }

    const conduitPath = `M ${slitX} ${slitTargetY} C ${slitX + 90} ${slitTargetY}, ${W - 120} ${conduitTargetY}, ${W} ${conduitTargetY}`;

    let layerHtml = `
      <!-- 1. Outer Glow Beam -->
      <path d="${laserPath}" fill="none" stroke="${laserColor}" stroke-width="12" opacity="0.45" filter="url(#neonLaser)"/>
      <path d="${conduitPath}" fill="none" stroke="${laserColor}" stroke-width="10" opacity="0.45" filter="url(#neonLaser)"/>

      <!-- 2. Colored Core Laser -->
      <path d="${laserPath}" fill="none" stroke="${laserColor}" stroke-width="4.5"/>
      <path d="${conduitPath}" fill="none" stroke="${laserColor}" stroke-width="3.5"/>

      <!-- 3. Bright White Electric Centerline -->
      <path d="${laserPath}" fill="none" stroke="#ffffff" stroke-width="2.2" class="laser-active-path" filter="drop-shadow(0 0 10px ${laserColor})"/>
      <path d="${conduitPath}" fill="none" stroke="#ffffff" stroke-width="1.8" class="laser-active-path" filter="drop-shadow(0 0 8px ${laserColor})"/>

      <!-- 4. Slit Reticle Rings -->
      <circle cx="${slitX}" cy="${slitTargetY}" r="15" fill="none" stroke="${laserColor}" stroke-width="2.6" filter="drop-shadow(0 0 12px ${laserColor})"/>
      <circle cx="${slitX}" cy="${slitTargetY}" r="7" fill="none" stroke="#ffffff" stroke-width="2.2"/>
      <circle cx="${slitX}" cy="${slitTargetY}" r="3.5" fill="${laserColor}"/>

      <!-- 5. Real-Time Photons on Laser Path -->
      <circle r="4" fill="#ffffff" filter="url(#${isBull ? 'greenGlow' : 'redGlow'})">
        <animateMotion path="${laserPath}" dur="0.9s" repeatCount="indefinite"/>
      </circle>
      <circle r="3.5" fill="#ffffff" filter="url(#${isBull ? 'greenGlow' : 'redGlow'})">
        <animateMotion path="${conduitPath}" dur="0.7s" begin="0.2s" repeatCount="indefinite"/>
      </circle>
    `;

    laserLayer.innerHTML = layerHtml;
  }

  window.highlightStockTrajectory = function (sym) {
    if (!sym) return;
    HOVERED_SYMBOL = sym;

    // 1. Highlight source row in left column
    document.querySelectorAll('.source-row').forEach(el => {
      const match = (el.dataset.sym || '').toUpperCase() === sym.toUpperCase();
      el.classList.toggle('active', match);
      el.classList.toggle('hovered', match);
    });

    // 2. Highlight buildup item in center columns
    document.querySelectorAll('.buildup-item').forEach(el => {
      const match = (el.dataset.sym || '').toUpperCase() === sym.toUpperCase();
      el.classList.toggle('highlighted', match);
      el.classList.toggle('active', match);
    });

    // 3. Highlight master card on right
    document.querySelectorAll('.master-card').forEach(el => {
      const match = (el.dataset.sym || '').toUpperCase() === sym.toUpperCase();
      el.classList.toggle('active', match);
    });

    // 4. Draw dynamic laser stream
    renderLaserTrajectory(sym);
  };

  function renderSankeyCanvas(data) {
    const currentMarketKey = data.market || 'crypto';
    if (SANKEY_INITIALIZED_MARKET !== currentMarketKey || !document.getElementById('sankey-bg-streams')) {
      initStaticSankeyCanvas(currentMarketKey);
    }
    renderLaserTrajectory(HOVERED_SYMBOL);
  }


  function createBuildupItemHtml(s) {
    if (!s) return '';
    const isBull = s.change_pct >= 0;
    const isHovered = s.symbol === HOVERED_SYMBOL;
    const barColor = isBull ? 'rgba(0, 255, 135, 0.45)' : 'rgba(255, 42, 85, 0.45)';
    const seed = Math.abs(Math.sin((s.cmp || 100) * 17)) * 1000;
    const w1 = (35 + (seed % 50)).toFixed(0);
    const w2 = (50 + ((seed * 3) % 45)).toFixed(0);
    const w3 = (25 + ((seed * 7) % 65)).toFixed(0);
    const w4 = (60 + ((seed * 11) % 35)).toFixed(0);
    return `
      <div class="buildup-item ${isHovered ? 'highlighted' : ''}" 
           id="buildup-${s.symbol}"
           data-sym="${s.symbol}"
           onmouseenter="showStockHover('${s.symbol}', this, event, 'full')"
           onmouseleave="hideStockHover()"
           onclick="openStockModal('${s.symbol}')">
        <div style="display:flex; justify-content:space-between; align-items:center; width:100%;">
          <div>
            <b class="buildup-sym blur-target">${s.symbol}</b>
          </div>
          <span style="font-family: var(--font-mono); color: ${isBull ? 'var(--bull-green)' : 'var(--bear-red)'}; font-size: 0.72rem; font-weight: 700;">
            ${s.change_pct > 0 ? '+' : ''}${s.change_pct.toFixed(2)}%
          </span>
        </div>
        <div class="buildup-micro-bars">
          <div style="height:3px; border-radius:1px; background:${barColor}; width:${w1}%;"></div>
          <div style="height:3px; border-radius:1px; background:${barColor}; width:${w2}%;"></div>
          <div style="height:3px; border-radius:1px; background:${barColor}; width:${w3}%;"></div>
          <div style="height:3px; border-radius:1px; background:${barColor}; width:${w4}%;"></div>
        </div>
      </div>
    `;
  }

  function createMasterCardHtml(s) {
    const isBull = s.change_pct >= 0;
    const sign = s.change_pct > 0 ? '+' : '';
    const riskPct = Math.abs(((s.cmp - s.s1) / s.cmp) * 100).toFixed(2);
    const isHovered = s.symbol === HOVERED_SYMBOL;

    return `
      <div class="master-card hud-card ${isBull ? 'bull' : 'bear'} ${isHovered ? 'active' : ''}" 
           id="master-${s.symbol}"
           data-sym="${s.symbol}"
           onmouseenter="showStockHover('${s.symbol}', this, event, 'full')"
           onmouseleave="hideStockHover()"
           onclick="openStockModal('${s.symbol}')">
        <div class="master-card-head">
          <div class="master-card-badge-row">
            <span class="master-radio-dot ${isBull ? 'bull' : 'bear'}"></span>
            <span class="tag-badge ${isBull ? 'bull' : 'bear'}">${isBull ? 'BULL' : 'BEAR'}</span>
            <b class="master-card-sym blur-target" style="color:#fff; margin-left:5px; font-size:0.88rem; font-weight:800;">${s.symbol}</b>
          </div>
          <span style="font-family: var(--font-mono); color: ${isBull ? 'var(--bull-green)' : 'var(--bear-red)'}; font-size:0.82rem; font-weight:800;">
            ${sign}${s.change_pct.toFixed(2)}%
          </span>
        </div>

        <div class="master-chart-wrap">
          ${renderMicroCandles(s.candles || s.sparkline, isBull, s.ob_high, s.ob_low)}
        </div>

        <div class="master-slider-row">
          <span style="color:${isBull ? 'var(--bull-green)' : 'var(--bear-red)'};">S1: ${fmtLevel(s.s1)}</span>
          <div class="slider-track">
            <div class="slider-knob ${isBull ? 'bull' : 'bear'}" style="left: ${isBull ? '65%' : '35%'};"></div>
          </div>
          <span style="color:${isBull ? 'var(--bull-green)' : 'var(--bear-red)'};">R2: ${fmtLevel(s.r2)}</span>
        </div>

        <div class="master-metrics-row">
          <span>ZONE: <b>${fmtLevel(s.zone)}</b></span>
          <span>RISK: <b>${riskPct}%</b></span>
          <span>R:R: <b style="color:${isBull ? 'var(--bull-green)' : 'var(--bear-red)'}">1 : ${s.rr}</b></span>
          <button type="button" class="btn-trade-radar" onclick="event.stopPropagation(); if (typeof window.loadStockIntoRadar === 'function') window.loadStockIntoRadar('${s.symbol}');" style="background:rgba(0,229,255,0.12); border:1px solid #00e5ff; color:#00e5ff; border-radius:4px; font-size:0.62rem; font-weight:800; padding:1px 5px; cursor:pointer; margin-left:auto;" title="Send setup directly to TradeRadar Execution Pipeline">⚡ Radar</button>
        </div>
      </div>
    `;
  }

  
  


  // ============================================================
  // REAL-TIME 5-MIN CANDLESTICK SVG CHART GENERATOR FOR HOVER CARD
  // ============================================================
  function generateFallbackCandles(stock) {
    const arr = [];
    let p = stock.base_price || stock.cmp * 0.98;
    const isBull = stock.change_pct >= 0;
    const drift = (stock.cmp - p) / 16;
    for (let i = 0; i < 16; i++) {
      const open = p;
      const change = drift + (Math.random() - 0.46) * (stock.cmp * 0.004);
      const close = open + change;
      const high = Math.max(open, close) + Math.random() * (stock.cmp * 0.003);
      const low = Math.min(open, close) - Math.random() * (stock.cmp * 0.003);
      arr.push({ open, high, low, close });
      p = close;
    }
    return arr;
  }

  function renderHoverCandlestickChart(stock) {
    const svg = document.getElementById('hover-candlestick-svg');
    if (!svg) return;
    const W = 350, H = 145;
    const isBull = stock.change_pct >= 0;
    const candles = stock.candles && stock.candles.length >= 10 ? stock.candles.slice(-16) : generateFallbackCandles(stock);

    const lows = candles.map(c => c.low);
    const highs = candles.map(c => c.high);
    const minP = Math.min(...lows, stock.s1 || stock.cmp * 0.96);
    const maxP = Math.max(...highs, stock.r2 || stock.cmp * 1.04);
    const range = maxP - minP || 1;
    const yVal = p => H - 16 - ((p - minP) / range) * (H - 32);

    const zoneColor = isBull ? '#00f0ff' : '#ff2a55';
    const zoneGradId = isBull ? 'obZoneGradBull' : 'obZoneGradBear';

    let html = `
      <defs>
        <linearGradient id="obZoneGradBull" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#00f0ff" stop-opacity="0.32"/>
          <stop offset="100%" stop-color="#00f0ff" stop-opacity="0.06"/>
        </linearGradient>
        <linearGradient id="obZoneGradBear" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#ff2a55" stop-opacity="0.32"/>
          <stop offset="100%" stop-color="#ff2a55" stop-opacity="0.06"/>
        </linearGradient>
      </defs>
    `;

    // 1. Shaded Order Block Zone Box
    const obTopY = yVal(stock.ob_high || stock.cmp * 1.01);
    const obBotY = yVal(stock.ob_low || stock.cmp * 0.99);
    const obH = Math.max(12, Math.abs(obBotY - obTopY));
    html += `
      <rect x="25" y="${Math.min(obTopY, obBotY).toFixed(1)}" width="${W - 50}" height="${obH.toFixed(1)}" 
            fill="url(#${zoneGradId})" stroke="${zoneColor}" stroke-width="1.2" stroke-dasharray="3,3" opacity="0.92"/>
      <text x="${W - 32}" y="${(Math.min(obTopY, obBotY) + obH/2 + 3).toFixed(1)}" fill="${zoneColor}" font-size="8" font-family="var(--font-mono)" font-weight="800" text-anchor="end">OB ZONE</text>
    `;

    // 2. Target and Support Reference Lines (Matching video frames 38s & 40s)
    if (isBull) {
      const r1Y = yVal(stock.r1 || stock.cmp * 1.02);
      const r2Y = yVal(stock.r2 || stock.cmp * 1.035);
      html += `
        <line x1="25" y1="${r1Y.toFixed(1)}" x2="${W - 25}" y2="${r1Y.toFixed(1)}" stroke="#00ff87" stroke-width="1" stroke-dasharray="3,3" opacity="0.85"/>
        <text x="28" y="${(r1Y - 3).toFixed(1)}" fill="#00ff87" font-size="7.5" font-family="var(--font-mono)">R1 ${fmtLevel(stock.r1||stock.cmp*1.02)}</text>
        
        <line x1="25" y1="${r2Y.toFixed(1)}" x2="${W - 25}" y2="${r2Y.toFixed(1)}" stroke="#00ff87" stroke-width="1.2" stroke-dasharray="3,3" opacity="0.95"/>
        <text x="28" y="${(r2Y - 3).toFixed(1)}" fill="#00ff87" font-size="7.5" font-family="var(--font-mono)">R2 ${fmtLevel(stock.r2||stock.cmp*1.035)}</text>
      `;

      const s1Y = yVal(stock.s1 || stock.cmp * 0.985);
      html += `
        <line x1="25" y1="${s1Y.toFixed(1)}" x2="${W - 25}" y2="${s1Y.toFixed(1)}" stroke="#fbbf24" stroke-width="1.2" stroke-dasharray="3,3" opacity="0.85"/>
        <text x="28" y="${(s1Y + 9).toFixed(1)}" fill="#fbbf24" font-size="7.5" font-family="var(--font-mono)">S1 ${fmtLevel(stock.s1||stock.cmp*0.985)}</text>
      `;
      if (stock.s2) {
        const s2Y = yVal(stock.s2);
        html += `
          <line x1="25" y1="${s2Y.toFixed(1)}" x2="${W - 25}" y2="${s2Y.toFixed(1)}" stroke="#f59e0b" stroke-width="0.9" stroke-dasharray="2,2" opacity="0.6"/>
          <text x="28" y="${(s2Y + 8).toFixed(1)}" fill="#f59e0b" font-size="7" font-family="var(--font-mono)">S2 ${fmtLevel(stock.s2)}</text>
        `;
      }
    } else {
      const rTop = yVal(stock.r1 || stock.cmp * 1.025);
      html += `
        <line x1="25" y1="${rTop.toFixed(1)}" x2="${W - 25}" y2="${rTop.toFixed(1)}" stroke="#f59e0b" stroke-width="1" stroke-dasharray="3,3" opacity="0.8"/>
        <text x="28" y="${(rTop - 3).toFixed(1)}" fill="#f59e0b" font-size="7.5" font-family="var(--font-mono)">R2 ${fmtLevel(stock.r1||stock.cmp*1.025)}</text>
      `;

      const s1Y = yVal(stock.s1 || stock.cmp * 0.98);
      const s2Y = yVal(stock.s2 || stock.cmp * 0.965);
      html += `
        <line x1="25" y1="${s1Y.toFixed(1)}" x2="${W - 25}" y2="${s1Y.toFixed(1)}" stroke="#ff2a55" stroke-width="1.2" stroke-dasharray="3,3" opacity="0.9"/>
        <text x="28" y="${(s1Y + 9).toFixed(1)}" fill="#ff2a55" font-size="7.5" font-family="var(--font-mono)">S1 ${fmtLevel(stock.s1||stock.cmp*0.98)}</text>
        
        <line x1="25" y1="${s2Y.toFixed(1)}" x2="${W - 25}" y2="${s2Y.toFixed(1)}" stroke="#ff2a55" stroke-width="1" stroke-dasharray="3,3" opacity="0.8"/>
        <text x="28" y="${(s2Y + 8).toFixed(1)}" fill="#ff2a55" font-size="7.5" font-family="var(--font-mono)">S2 ${fmtLevel(stock.s2||stock.cmp*0.965)}</text>
      `;
    }

    // 3. Candlesticks (Green for bull, Red for bear)
    const numC = candles.length;
    const chartW = W - 60;
    const stepX = chartW / numC;
    const bodyW = Math.max(5, stepX * 0.68);

    candles.forEach((c, i) => {
      const cx = 35 + i * stepX + stepX / 2;
      const oY = yVal(c.open);
      const cY = yVal(c.close);
      const hY = yVal(c.high);
      const lY = yVal(c.low);
      const up = c.close >= c.open;
      const color = up ? 'var(--bull-green)' : 'var(--bear-red)';
      const topY = Math.min(oY, cY);
      const bH = Math.max(3, Math.abs(cY - oY));

      html += `<line x1="${cx.toFixed(1)}" y1="${hY.toFixed(1)}" x2="${cx.toFixed(1)}" y2="${lY.toFixed(1)}" stroke="${color}" stroke-width="1.3"/>`;
      html += `<rect x="${(cx - bodyW / 2).toFixed(1)}" y="${topY.toFixed(1)}" width="${bodyW.toFixed(1)}" height="${bH.toFixed(1)}" fill="${color}" rx="1"/>`;
    });

    // 4. Time Axis labels
    const tTimes = ['09:30', '10:00', '10:30', '11:00', '11:30'];
    tTimes.forEach((t, i) => {
      const x = 35 + (i / (tTimes.length - 1)) * chartW;
      html += `<text x="${x.toFixed(1)}" y="${H - 4}" fill="#64748b" font-size="7" font-family="var(--font-mono)" text-anchor="middle">${t}</text>`;
    });

    svg.innerHTML = html;
  }

  // ============================================================
  // INSTANT 0-MS HOVER ENGINE (MATCHING VIDEO)
  // ============================================================
  window.showStockHover = function (sym, element, evt, forcedMode) {
    clearTimeout(hoverTimer);
    activeHoverElement = element;

    const hoverCard = document.getElementById('hover-stock-card');
    if (!hoverCard) return;

    // Robust symbol normalization
    if (!sym && element && element.dataset) {
      sym = element.dataset.sym || element.dataset.symbol;
    }
    if (!sym) {
      const tkr = element && element.querySelector && element.querySelector('.source-sym, .master-card-sym, .buildup-sym, .tkr');
      if (tkr) sym = tkr.textContent.trim();
    }
    sym = String(sym || 'BTC').trim();
    if (typeof window.highlightStockTrajectory === 'function') window.highlightStockTrajectory(sym);

    // Retrieve stock data from MARKET_DATA or realistic fallback
    let stock = (MARKET_DATA && MARKET_DATA.stocks) ? MARKET_DATA.stocks[sym] : null;
    if (!stock && MARKET_DATA && MARKET_DATA.stocks) {
      const symUpper = sym.toUpperCase();
      const key = Object.keys(MARKET_DATA.stocks).find(k => k.toUpperCase() === symUpper);
      if (key) stock = MARKET_DATA.stocks[key];
    }
    if (!stock) {
      const base = 850;
      stock = {
        symbol: sym,
        name: sym + ' Industries Ltd',
        sector: 'NIFTY 50',
        cmp: base,
        base_price: base,
        change_pct: 2.15,
        ob_high: base * 1.012,
        ob_low: base * 0.992,
        s1: base * 0.982,
        s2: base * 0.970,
        s3: base * 0.958,
        s4: base * 0.945,
        r1: base * 1.025,
        r2: base * 1.042,
        sparkline: [base*0.98, base*0.988, base*1.002, base*1.015, base*1.021],
        candles: []
      };
    }

    const isBull = stock.change_pct >= 0;
    const sign = stock.change_pct > 0 ? '+' : '';
    const oiVal = (Math.abs(stock.change_pct) * 2.3 + 4.8).toFixed(1);
    const rrRatio = (Math.abs((stock.r1 - stock.cmp) / Math.max(0.1, stock.cmp - stock.s1)) || 2.7).toFixed(1);

    // Determine Mode: 'compact' (Left list) vs 'full' (Right Master cards / Center cards)
    const isSourceRow = element.classList.contains('source-row') || (element.closest && element.closest('.source-row'));
    const mode = forcedMode || (isSourceRow ? 'compact' : 'full');

    const compactSec = document.getElementById('h-compact-section');
    const fullSec = document.getElementById('h-full-section');
    if (mode === 'compact') {
      if (compactSec) compactSec.style.display = 'grid';
      if (fullSec) fullSec.style.display = 'none';
      hoverCard.style.width = '330px';
    } else {
      if (compactSec) compactSec.style.display = 'none';
      if (fullSec) fullSec.style.display = 'block';
      hoverCard.style.width = '380px';
    }

    // Populate common header
    const hSym = document.getElementById('h-sym');
    const hName = document.getElementById('h-name');
    const hSec = document.getElementById('h-sector');
    const hBias = document.getElementById('h-bias');
    const hPrice = document.getElementById('h-price');
    const hChg = document.getElementById('h-chg');

    if (hSym) hSym.textContent = stock.symbol;
    if (hName) hName.textContent = stock.name || (stock.symbol + ' Ltd');
    if (hSec) {
      hSec.textContent = stock.sector;
      hSec.className = `hover-badge ${isBull ? 'bull' : 'bear'}`;
    }
    if (hBias) {
      hBias.textContent = isBull ? 'BULLISH #1' : 'BEARISH #1';
      hBias.className = `hover-badge ${isBull ? 'bull' : 'bear'}`;
    }
    if (hPrice) hPrice.textContent = fmtPrice(stock.cmp);
    if (hChg) {
      hChg.textContent = `${sign}${stock.change_pct.toFixed(2)}%`;
      hChg.className = `hover-chg-val ${isBull ? 'up' : 'down'}`;
    }

    // Populate Compact Mode Fields
    const setTxt = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
    setTxt('h-c-rank', `p99.8 · #${stock.rank || 1}/120`);
    setTxt('h-c-oi', `+${oiVal}% · ${isBull ? 'LONG BUILD-UP' : 'SHORT BUILD-UP'}`);
    setTxt('h-c-delta', `${sign}${(Math.abs(stock.change_pct) * 1.8).toFixed(1)}%`);
    setTxt('h-c-gate', isBull ? 'BULLISH BREAKOUT' : 'BEARISH BREAKDOWN');

    // Populate Full Mode Fields
    setTxt('h-rank', `p99.8 · #${stock.rank || 1}/130`);
    setTxt('h-rule', 'ORDER BLOCK RETEST');
    setTxt('h-ob', `${fmtLevel(stock.ob_low)} - ${fmtLevel(stock.ob_high)}`);
    setTxt('h-s1', fmtLevel(stock.s1));
    setTxt('h-r1', fmtLevel(stock.r1));
    setTxt('h-r2', fmtLevel(stock.r2));
    setTxt('h-rr', `1 : ${rrRatio}`);
    setTxt('h-oi', `+${oiVal}%`);
    setTxt('h-vwap', fmtPrice(stock.cmp * 0.996));
    setTxt('h-conv', isBull ? 'HIGH (MSB)' : 'HIGH (CHoCH)');

    setTxt('h-s1-lbl', fmtLevel(stock.s1));
    setTxt('h-z-lbl', fmtLevel(stock.ob_low));
    setTxt('h-r1-lbl', fmtLevel(stock.r1));
    setTxt('h-r2-lbl', fmtLevel(stock.r2));

    // Slider
    const sTrackPct = isBull ? 68 : 32;
    const pin = document.getElementById('h-slider-pin');
    const fill = document.getElementById('h-slider-fill');
    if (pin) pin.style.left = `${sTrackPct}%`;
    if (fill) fill.style.width = `${sTrackPct}%`;

    // Render full Candlestick chart if in full mode
    if (mode === 'full') {
      renderHoverCandlestickChart(stock);
    }

    // Smart screen positioning based on caller position
    const rect = element.getBoundingClientRect();
    const cardW = mode === 'compact' ? 330 : 380;
    const cardH = mode === 'compact' ? 240 : 410;
    const vw = window.innerWidth;
    const vh = window.innerHeight;

    let left, top;
    const isMasterCard = element.classList.contains('master-card') || (element.closest && element.closest('.master-card'));
    const isBuildupItem = element.classList.contains('buildup-item') || (element.closest && element.closest('.buildup-item'));
    const isHomePick = element.classList.contains('pick') || element.classList.contains('pick-card') || (element.closest && element.closest('.pick, .pick-card'));

    if (isSourceRow) {
      left = rect.right + 14;
      top = Math.max(12, Math.min(rect.top - 10, vh - cardH - 14));
    } else if (isMasterCard) {
      left = rect.left - cardW - 14;
      top = Math.max(12, Math.min(rect.top - 20, vh - cardH - 14));
    } else if (isBuildupItem) {
      left = Math.max(12, Math.min(rect.left - 40, vw - cardW - 14));
      if (rect.bottom + cardH + 14 < vh) {
        top = rect.bottom + 8;
      } else {
        top = Math.max(12, rect.top - cardH - 8);
      }
    } else if (isHomePick) {
      if (isBull) {
        left = rect.right + 14;
        if (left + cardW > vw - 12) left = rect.left - cardW - 14;
      } else {
        left = rect.left - cardW - 14;
        if (left < 12) left = rect.right + 14;
      }
      top = Math.max(12, Math.min(rect.top - 20, vh - cardH - 14));
    } else {
      left = (rect.right + cardW < vw - 12) ? rect.right + 14 : rect.left - cardW - 14;
      top = Math.max(12, Math.min(rect.top, vh - cardH - 14));
    }

    left = Math.max(10, Math.min(left, vw - cardW - 10));
    top = Math.max(10, Math.min(top, vh - cardH - 10));

    hoverCard.style.left = left + 'px';
    hoverCard.style.top = top + 'px';
    hoverCard.style.removeProperty('transform');
    hoverCard.style.display = 'block';

    // Instant smooth appearance without forced reflow
    hoverCard.className = `hover-floating-card visible ${isBull ? 'bull' : 'bear'}`;

    // Update laser beam trajectory on central neural canvas
    if (typeof window.highlightStockTrajectory === 'function') {
      window.highlightStockTrajectory(stock.symbol);
    }
  };

  window.hideStockHover = function () {
    clearTimeout(hoverTimer);
    hoverTimer = setTimeout(() => {
      const hoverCard = document.getElementById('hover-stock-card');
      if (hoverCard) {
        hoverCard.classList.remove('visible');
        setTimeout(() => {
          if (!hoverCard.classList.contains('visible')) {
            hoverCard.style.display = 'none';
          }
        }, 80);
      }
      activeHoverElement = null;
    }, 35); // 35ms instant response
  };

  // Wire hover card itself to keep open when mouse enters
  const hCardEl = document.getElementById('hover-stock-card');
  if (hCardEl) {
    hCardEl.addEventListener('mouseenter', () => {
      clearTimeout(hoverTimer);
    });
    hCardEl.addEventListener('mouseleave', () => {
      window.hideStockHover();
    });
  }

  // Delegated global hover listener for official Home view picks and dynamic elements
  document.addEventListener('mouseover', e => {
    const pickEl = e.target.closest && e.target.closest('.pick, [data-sym], .source-row, .buildup-item, .master-card');
    if (!pickEl) return;
    
    let sym = pickEl.dataset.sym || pickEl.dataset.symbol;
    if (!sym) {
      const tkrEl = pickEl.querySelector('.tkr') || pickEl.querySelector('.source-sym') || pickEl.querySelector('.buildup-sym') || pickEl.querySelector('.master-card-sym');
      if (tkrEl) sym = tkrEl.textContent.trim();
    }
    if (sym && typeof window.showStockHover === 'function') {
      const isSrc = pickEl.classList.contains('source-row') || (pickEl.closest && pickEl.closest('.source-row'));
      window.showStockHover(sym, pickEl, e, isSrc ? 'compact' : 'full');
    }
  });

  document.addEventListener('mouseout', e => {
    const pickEl = e.target.closest && e.target.closest('.pick, [data-sym], .source-row, .buildup-item, .master-card');
    if (!pickEl) return;
    const to = e.relatedTarget;
    if (!to || !pickEl.contains(to)) {
      if (typeof window.hideStockHover === 'function') {
        window.hideStockHover();
      }
    }
  });


  // ============================================================
  // 10-SECOND DETAIL MODAL CLICK HANDLERS
  // ============================================================
  window.openStockModal = function (sym) {
    if (!sym && activeHoverElement) {
      sym = activeHoverElement.dataset.sym || activeHoverElement.dataset.symbol;
    }
    sym = String(sym || 'BTC').trim();
    if (typeof window.highlightStockTrajectory === 'function') window.highlightStockTrajectory(sym);
    ACTIVE_MODAL_SYMBOL = sym;
    const modal = document.getElementById('stockModalOverlay');
    if (!modal) return;
    modal.style.display = 'flex';
    modal.classList.add('active');

    let stock = (MARKET_DATA && MARKET_DATA.stocks) ? MARKET_DATA.stocks[sym] : null;
    if (!stock && MARKET_DATA && MARKET_DATA.stocks) {
      const symUpper = sym.toUpperCase();
      const key = Object.keys(MARKET_DATA.stocks).find(k => k.toUpperCase() === symUpper);
      if (key) stock = MARKET_DATA.stocks[key];
    }
    if (stock) {
      renderModalData(stock);
    }
  };

  window.closeStockModal = function () {
    ACTIVE_MODAL_SYMBOL = null;
    const modal = document.getElementById('stockModalOverlay');
    if (modal) {
      modal.style.display = 'none';
      modal.classList.remove('active');
    }
  };

  window.closeModalOnBackdrop = function (e) {
    if (e && e.target && e.target.id === 'stockModalOverlay') {
      window.closeStockModal();
    }
  };

  function renderModalData(s) {
    document.getElementById('modal-symbol').textContent = s.symbol;
    document.getElementById('modal-sector').textContent = s.sector;
    document.getElementById('modal-bias-badge').textContent = s.rule;
    document.getElementById('modal-bias-badge').className = `tag-badge ${s.change_pct >= 0 ? 'bull' : 'bear'}`;

    document.getElementById('modal-cmp').textContent = `₹${s.cmp.toFixed(2)}`;
    const chgEl = document.getElementById('modal-chg');
    chgEl.textContent = `${s.change_pct > 0 ? '+' : ''}${s.change_pct.toFixed(2)}%`;
    chgEl.className = `modal-chg-val ${s.change_pct >= 0 ? 'up' : 'down'}`;

    // Metrics grid
    document.getElementById('m-rank').textContent = `${s.rank_p} · ${s.rank_side}`;
    document.getElementById('m-rule').textContent = s.rule;
    document.getElementById('m-ob').textContent = `${s.ob_low.toFixed(2)} - ${s.ob_high.toFixed(2)}`;
    document.getElementById('m-zs1').textContent = `${s.zone.toFixed(2)} / ${s.s1.toFixed(2)}`;
    document.getElementById('m-rr').textContent = `1 : ${s.rr}`;
    document.getElementById('m-r1r2').textContent = `${s.r1.toFixed(2)} / ${s.r2.toFixed(2)}`;
    document.getElementById('m-oi').textContent = `${s.oi_pct > 0 ? '+' : ''}${s.oi_pct}%`;
    document.getElementById('m-vwap').textContent = `₹${s.vwap.toFixed(2)}`;
    document.getElementById('m-delta').textContent = `${s.delta > 0 ? '+' : ''}${s.delta}`;

    // Slider numbers
    document.getElementById('lbl-s1').textContent = s.s1.toFixed(2);
    document.getElementById('lbl-z').textContent = s.zone.toFixed(2);
    document.getElementById('lbl-r1').textContent = s.r1.toFixed(2);
    document.getElementById('lbl-r2').textContent = s.r2.toFixed(2);

    const totalSpan = Math.abs(s.r2 - s.s1) || 1;
    const currDist = Math.abs(s.cmp - s.s1);
    const sliderPct = Math.min(95, Math.max(5, (currDist / totalSpan) * 100));
    document.getElementById('modal-slider-fill').style.width = `${sliderPct}%`;
    document.getElementById('modal-slider-pin').style.left = `${sliderPct}%`;

    renderModalCandlestickChart(s);
  }

  function renderModalCandlestickChart(s) {
    const svg = document.getElementById('modal-candlestick-svg');
    if (!svg || !s.candles) return;

    const W = 690, H = 250;
    const candles = s.candles;
    const lows = candles.map(c => c.low);
    const highs = candles.map(c => c.high);
    const minP = Math.min(...lows, s.s1, s.ob_low) * 0.998;
    const maxP = Math.max(...highs, s.r2, s.ob_high) * 1.002;
    const range = maxP - minP || 1;

    const yVal = p => H - 20 - ((p - minP) / range) * (H - 40);

    let svgHtml = `
      <!-- Price Grid Lines -->
      <line x1="0" y1="${yVal(s.r2)}" x2="${W}" y2="${yVal(s.r2)}" stroke="#00ff87" stroke-dasharray="3,3" stroke-width="1.2" opacity="0.6"/>
      <text x="${W - 65}" y="${yVal(s.r2) - 4}" fill="#00ff87" font-size="9" font-family="JetBrains Mono" font-weight="700">R2: ${s.r2}</text>

      <line x1="0" y1="${yVal(s.r1)}" x2="${W}" y2="${yVal(s.r1)}" stroke="#00ff87" stroke-dasharray="2,2" stroke-width="1" opacity="0.5"/>
      <text x="${W - 65}" y="${yVal(s.r1) - 4}" fill="#00ff87" font-size="9" font-family="JetBrains Mono" font-weight="700">R1: ${s.r1}</text>

      <line x1="0" y1="${yVal(s.zone)}" x2="${W}" y2="${yVal(s.zone)}" stroke="#00f0ff" stroke-dasharray="4,4" stroke-width="1.5" filter="drop-shadow(0 0 4px #00f0ff)"/>
      <text x="10" y="${yVal(s.zone) - 4}" fill="#00f0ff" font-size="10" font-family="JetBrains Mono" font-weight="800">ZONE (Z): ${s.zone}</text>

      <line x1="0" y1="${yVal(s.s1)}" x2="${W}" y2="${yVal(s.s1)}" stroke="#ff2a55" stroke-width="1.5" filter="drop-shadow(0 0 4px #ff2a55)"/>
      <text x="${W - 85}" y="${yVal(s.s1) + 12}" fill="#ff2a55" font-size="9" font-family="JetBrains Mono" font-weight="800">S1 (STOP): ${s.s1}</text>
    `;

    // Order Block Shaded Box
    const obTop = yVal(Math.max(s.ob_high, s.ob_low));
    const obBot = yVal(Math.min(s.ob_high, s.ob_low));
    const obHeight = Math.max(8, obBot - obTop);
    svgHtml += `
      <rect x="0" y="${obTop}" width="${W}" height="${obHeight}" fill="${s.change_pct >= 0 ? '#00ff87' : '#ff2a55'}" fill-opacity="0.14" stroke="#fbbf24" stroke-width="1.2" stroke-dasharray="2,2"/>
      <text x="${W/2 - 50}" y="${obTop + obHeight/2 + 4}" fill="#fbbf24" font-size="10" font-family="JetBrains Mono" font-weight="800">ORDER BLOCK (OB)</text>
    `;

    // Horizontal Price Lines (R2, R1, Z, S1, S2, S3, S4)
    const s2 = s.s1 * 0.995;
    const s3 = s.s1 * 0.990;
    const s4 = s.s1 * 0.985;

    svgHtml += `
      <!-- Price Grid Lines -->
      <line x1="0" y1="${yVal(s.r2)}" x2="${W}" y2="${yVal(s.r2)}" stroke="#00ff87" stroke-dasharray="3,3" stroke-width="1.2" opacity="0.6"/>
      <text x="${W - 65}" y="${yVal(s.r2) - 4}" fill="#00ff87" font-size="9" font-family="JetBrains Mono" font-weight="700">R2: ${fmtLevel(s.r2)}</text>

      <line x1="0" y1="${yVal(s.r1)}" x2="${W}" y2="${yVal(s.r1)}" stroke="#00ff87" stroke-dasharray="2,2" stroke-width="1" opacity="0.5"/>
      <text x="${W - 65}" y="${yVal(s.r1) - 4}" fill="#00ff87" font-size="9" font-family="JetBrains Mono" font-weight="700">R1: ${s.r1.toFixed(1)}</text>

      <line x1="0" y1="${yVal(s.zone)}" x2="${W}" y2="${yVal(s.zone)}" stroke="#00f0ff" stroke-dasharray="4,4" stroke-width="1.5" filter="drop-shadow(0 0 4px #00f0ff)"/>
      <text x="10" y="${yVal(s.zone) - 4}" fill="#00f0ff" font-size="10" font-family="JetBrains Mono" font-weight="800">ZONE (Z): ${s.zone.toFixed(1)}</text>

      <line x1="0" y1="${yVal(s.s1)}" x2="${W}" y2="${yVal(s.s1)}" stroke="#fbbf24" stroke-width="1.4"/>
      <text x="${W - 85}" y="${yVal(s.s1) - 3}" fill="#fbbf24" font-size="9" font-family="JetBrains Mono" font-weight="700">S1: ${fmtLevel(s.s1)}</text>

      <line x1="0" y1="${yVal(s2)}" x2="${W}" y2="${yVal(s2)}" stroke="#f59e0b" stroke-dasharray="2,2" stroke-width="1" opacity="0.7"/>
      <text x="${W - 85}" y="${yVal(s2) - 3}" fill="#f59e0b" font-size="9" font-family="JetBrains Mono">S2: ${s2.toFixed(1)}</text>

      <line x1="0" y1="${yVal(s3)}" x2="${W}" y2="${yVal(s3)}" stroke="#ef4444" stroke-dasharray="2,2" stroke-width="1" opacity="0.7"/>
      <text x="${W - 85}" y="${yVal(s3) - 3}" fill="#ef4444" font-size="9" font-family="JetBrains Mono">S3: ${s3.toFixed(1)}</text>

      <line x1="0" y1="${yVal(s4)}" x2="${W}" y2="${yVal(s4)}" stroke="#dc2626" stroke-dasharray="2,2" stroke-width="1" opacity="0.7"/>
      <text x="${W - 85}" y="${yVal(s4) - 3}" fill="#dc2626" font-size="9" font-family="JetBrains Mono">S4: ${s4.toFixed(1)}</text>
    `;

    // Candlesticks
    const candleW = 12;
    const step = (W - 120) / candles.length;
    candles.forEach((c, i) => {
      const x = 30 + i * step;
      const isGreen = c.close >= c.open;
      const color = isGreen ? '#00ff87' : '#ff2a55';
      const wickTop = yVal(c.high);
      const wickBot = yVal(c.low);
      const bodyTop = yVal(Math.max(c.open, c.close));
      const bodyBot = yVal(Math.min(c.open, c.close));
      const bodyH = Math.max(2, bodyBot - bodyTop);

      svgHtml += `
        <line x1="${(x + candleW/2).toFixed(1)}" y1="${wickTop.toFixed(1)}" x2="${(x + candleW/2).toFixed(1)}" y2="${wickBot.toFixed(1)}" stroke="${color}" stroke-width="1.2"/>
        <rect x="${x.toFixed(1)}" y="${bodyTop.toFixed(1)}" width="${candleW}" height="${bodyH.toFixed(1)}" rx="1" fill="${color}" filter="drop-shadow(0 0 2px ${color})"/>
      `;
    });

    // Time Axis at Bottom
    const timeLabels = ['09:30', '10:30', '11:30', '12:30', '13:30', '14:30', '15:30'];
    timeLabels.forEach((t, i) => {
      const x = 30 + (i / (timeLabels.length - 1)) * (W - 120);
      svgHtml += `<text x="${x.toFixed(1)}" y="${H - 4}" fill="#475569" font-size="8.5" font-family="JetBrains Mono" text-anchor="middle">${t}</text>`;
    });

    // Centered Lock Badge (from Image 2)
    svgHtml += `
      <g style="cursor:pointer;" onclick="openUnlockModal()">
        <rect x="${W/2 - 80}" y="${H/2 - 16}" width="160" height="32" rx="16" fill="rgba(8, 12, 22, 0.9)" stroke="#7c3aed" stroke-width="1.5" filter="drop-shadow(0 0 10px rgba(124, 58, 237, 0.5))"/>
        <text x="${W/2}" y="${H/2 + 5}" fill="#fff" font-size="10.5" font-family="Inter Tight" font-weight="700" text-anchor="middle">🔒 ACCESS LOCKED</text>
      </g>
    `;

    svg.innerHTML = svgHtml;
  }

  window.toggleGuestBlur = function () {
    const isBlur = document.body.classList.toggle('guest-blur-active');
    const txt = document.getElementById('blurStateText');
    if (txt) {
      txt.textContent = isBlur ? 'ON (Video Style)' : 'OFF (Crisp)';
      txt.style.color = isBlur ? '#f59e0b' : '#38bdf8';
    }
  };

  // ---------------- VIEW SWITCHING & INTERACTIONS ----------------
  window.switchView = function (viewName) {
    CURRENT_VIEW = viewName;
    const obView = document.getElementById('view-orderblock');
    const homeView = document.getElementById('view-home');
    const btnOb = document.getElementById('btnToggleOrderblock');
    const btnHome = document.getElementById('btnToggleHome');
    const navOb = document.getElementById('nav-orderblock');
    const navHome = document.getElementById('nav-home');

    if (viewName === 'home') {
      if (homeView) homeView.style.display = 'grid';
      if (obView) obView.style.display = 'none';
      if (btnOb) {
        btnOb.style.background = '';
        btnOb.style.borderColor = '';
        btnOb.style.color = '';
      }
      if (btnHome) {
        btnHome.style.background = '#0e281e';
        btnHome.style.borderColor = '#00ff87';
        btnHome.style.color = '#00ff87';
      }
      if (navOb) navOb.classList.remove('on');
      if (navHome) navHome.classList.add('on');
    } else {
      if (homeView) homeView.style.display = 'none';
      if (obView) obView.style.display = 'flex';
      if (btnOb) {
        btnOb.style.background = '#0e281e';
        btnOb.style.borderColor = '#00ff87';
        btnOb.style.color = '#00ff87';
      }
      if (btnHome) {
        btnHome.style.background = '';
        btnHome.style.borderColor = '';
        btnHome.style.color = '';
      }
      if (navOb) navOb.classList.add('on');
      if (navHome) navHome.classList.remove('on');
      if (MARKET_DATA) renderOrderBlockView(MARKET_DATA);
    }
  };

  const collapseBtn = document.getElementById('collapseSidebar');
  const sidebar = document.getElementById('sidebar');
  if (collapseBtn && sidebar) {
    collapseBtn.addEventListener('click', () => {
      sidebar.classList.toggle('collapsed');
      document.body.classList.toggle('rail');
    });
  }

  const themeToggle = document.getElementById('themeToggleBtn');
  if (themeToggle) {
    themeToggle.addEventListener('click', e => {
      const btn = e.target.closest('button[data-set]');
      if (!btn) return;
      const theme = btn.dataset.set;
      document.documentElement.setAttribute('data-theme', theme);
      themeToggle.querySelectorAll('button[data-set]').forEach(b => {
        b.classList.toggle('on', b === btn);
      });
    });
  }

  window.openUnlockModal = function () {
    window.toggleGuestBlur();
  };

  // ---------------- LIVE SEARCH FILTER & KEYBOARD SHORTCUTS ----------------
  const searchInput = document.getElementById('stockSearchInput');
  if (searchInput) {
    searchInput.addEventListener('input', e => {
      const q = (e.target.value || '').trim().toUpperCase();
      const rows = document.querySelectorAll('.source-row');
      rows.forEach(r => {
        const sym = (r.dataset.sym || '').toUpperCase();
        if (!q || sym.includes(q)) {
          r.style.display = 'flex';
        } else {
          r.style.display = 'none';
        }
      });
      if (q) {
        const match = Array.from(rows).find(r => (r.dataset.sym || '').toUpperCase().startsWith(q));
        if (match) {
          const sym = match.dataset.sym;
          if (typeof window.highlightStockTrajectory === 'function') {
            window.highlightStockTrajectory(sym);
          }
        }
      }
    });

    searchInput.addEventListener('keydown', e => {
      if (e.key === 'Enter') {
        const visible = Array.from(document.querySelectorAll('.source-row')).filter(r => r.style.display !== 'none');
        if (visible.length > 0) {
          const sym = visible[0].dataset.sym;
          if (typeof window.showStockHover === 'function') {
            window.showStockHover(sym, visible[0], null, 'compact');
          }
        }
      }
    });
  }

  // Global Keyboard Shortcuts
  document.addEventListener('keydown', e => {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
      e.preventDefault();
      window.switchView('orderblock');
      const s = document.getElementById('stockSearchInput');
      if (s) { s.focus(); s.select(); }
    }
    if (e.key === 'Escape') {
      if (typeof window.closeStockModal === 'function') window.closeStockModal();
      if (typeof window.hideStockHover === 'function') window.hideStockHover();
    }
  });


  // Bootloader
  startClientPulse();
  initDataStream();

})();
